/* ================= v46: accessibility ================= */
const A11Y_DEF={size:1,contrast:false,motion:'system',font:'default',focus:true};
function a11y(){return Object.assign({},A11Y_DEF,store.get('a11y',{})||{})}
function a11ySet(k,v){const a=a11y();a[k]=v;store.set('a11y',a);applyA11y()}
let _a11yFont=false;
function applyA11y(){const a=a11y(),r=document.documentElement;if(!r.lang)r.lang='en';r.style.setProperty('--a11y-z',String(a.size||1));
 r.toggleAttribute('data-a11y-contrast',!!a.contrast);r.toggleAttribute('data-a11y-still',a.motion==='reduce');r.toggleAttribute('data-a11y-font',a.font==='readable');
 if(a.font==='readable'&&!_a11yFont){_a11yFont=true;const l=document.createElement('link');l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:ital,wght@0,400;0,700;1,400&display=swap';document.head.appendChild(l)}}
/* a skip link and one shared place to announce things to screen readers */
function a11yChrome(){if(document.getElementById('skiplink'))return;const sk=document.createElement('a');sk.id='skiplink';sk.className='skiplink';sk.href='#';sk.textContent='Skip to main content';
 sk.onclick=e=>{e.preventDefault();const h=document.querySelector('#main h1,#main h2')||document.getElementById('main');if(h){if(!h.hasAttribute('tabindex'))h.setAttribute('tabindex','-1');h.focus()}};document.body.prepend(sk);
 const lv=document.createElement('div');lv.id='a11ylive';lv.className='sr-only';lv.setAttribute('aria-live','polite');lv.setAttribute('aria-atomic','true');document.body.appendChild(lv)}
function announce(t){const lv=document.getElementById('a11ylive');if(!lv)return;lv.textContent='';setTimeout(()=>{lv.textContent=t},60)}
/* after moving to another page: name the page, and if keyboard focus was lost with the old page, put it on the new heading */
let _a11yFirst=true;
function a11yRoute(){setTimeout(()=>{const h=document.querySelector('#main h1')||document.querySelector('#main h2');const name=h?h.textContent.replace(/\s+/g,' ').trim().slice(0,80):'';
 if(name)document.title=name+' · Theory Club';if(_a11yFirst){_a11yFirst=false;return}if(name)announce(name);
 const ae=document.activeElement;if(a11y().focus&&h&&(!ae||ae===document.body||!ae.isConnected)){if(!h.hasAttribute('tabindex'))h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}},120)}
window.addEventListener('hashchange',a11yRoute);
/* settings */
function a11yHTML(){const a=a11y();return`<div class="pickrow" id="a11yset"><span class="eyebrow">Accessibility</span>
 <div class="pickrow"><span class="hint">Text size</span>${pillsHTML('a11ysize',[['1','Standard'],['1.15','Large'],['1.3','Larger']],String(a.size||1))}</div>
 <label class="row a11ychk"><input type="checkbox" data-a11y="contrast" ${a.contrast?'checked':''}> <span>High contrast <span class="hint">stronger text, borders and focus rings</span></span></label>
 <label class="row a11ychk"><input type="checkbox" data-a11y="motion" ${a.motion==='reduce'?'checked':''}> <span>Reduce motion <span class="hint">no animations or moving highlights</span></span></label>
 <label class="row a11ychk"><input type="checkbox" data-a11y="font" ${a.font==='readable'?'checked':''}> <span>Easy-to-read font <span class="hint">Atkinson Hyperlegible, designed for low vision</span></span></label>
 <label class="row a11ychk"><input type="checkbox" data-a11y="focus" ${a.focus?'checked':''}> <span>Move focus to the new page <span class="hint">helps screen reader and keyboard users</span></span></label>
 <p class="hint">Keyboard: Tab moves between controls, and the “Skip to main content” link appears first. In the song transcriber, Space plays or pauses and the arrow keys move through the bars.</p></div>`}
function a11yBind(body){const s=body.querySelector('#a11yset');if(!s)return;bindPills(s,(g,v)=>{if(g==='a11ysize'){a11ySet('size',+v);s.querySelectorAll('[data-group=a11ysize] .pill').forEach(b=>b.setAttribute('aria-pressed',b.dataset.v===v))}});
 s.querySelectorAll('[data-a11y]').forEach(c=>c.onchange=()=>{const k=c.dataset.a11y;a11ySet(k,k==='motion'?(c.checked?'reduce':'system'):k==='font'?(c.checked?'readable':'default'):c.checked)})}
{const _os=openSettings;openSettings=function(){const r=_os.apply(this,arguments);try{const body=document.getElementById('setbody');const add=()=>{if(!body.querySelector('#a11yset')){const del=body.querySelector('.delzone');const w=document.createElement('div');w.innerHTML=a11yHTML();(del?del.before(w.firstElementChild):body.appendChild(w.firstElementChild));a11yBind(body)}};add();
  if(!body._a11yObs){body._a11yObs=new MutationObserver(()=>{if(!body.querySelector('#a11yset'))add()});body._a11yObs.observe(body,{childList:true})}}catch(e){}return r}}
/* song transcriber from the keyboard, and the notes as text for screen readers */
function tsKeys(e){if(!/^#tools-isolate/.test(location.hash))return;const t=e.target;if(t&&(/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)||t.isContentEditable))return;if(e.ctrlKey||e.metaKey||e.altKey)return;
 const pb=document.getElementById('tsplay');if(!pb)return;const bars=[...document.querySelectorAll('.tstab .tsbar')];const cur=()=>{const tm=tsTime();let k=0;bars.forEach((b,i)=>{const g=+b.dataset.bar*16;try{if(tsGridTime(TS.res.beats,g)<=tm+.01)k=i}catch(x){}});return k};
 const go=i=>{i=Math.max(0,Math.min(bars.length-1,i));const b=bars[i];if(!b)return;b.click();announce('Bar '+(i+1));b.scrollIntoView({block:'nearest',inline:'center',behavior:a11y().motion==='reduce'?'auto':'smooth'})};
 if(e.key===' '&&!(t&&t.tagName==='BUTTON')){e.preventDefault();pb.click();setTimeout(()=>announce(tsPlaying()?'Playing':'Paused'),120)}
 else if(e.key==='ArrowRight'&&bars.length&&(t.closest&&t.closest('.tstab')||e.shiftKey)){e.preventDefault();go(cur()+1)}
 else if(e.key==='ArrowLeft'&&bars.length&&(t.closest&&t.closest('.tstab')||e.shiftKey)){e.preventDefault();go(cur()-1)}
 else if(e.key==='Home'&&t.closest&&t.closest('.tstab')){e.preventDefault();const rw=document.getElementById('tsrw');if(rw)rw.click();announce('Back to the start')}
 else if(e.key==='Enter'&&t.closest&&t.closest('.tstab')){e.preventDefault();if(!tsPlaying())pb.click()}
 else if(e.key==='['){const b=document.getElementById('tsla');if(b){b.click();announce('Loop starts here')}}
 else if(e.key===']'){const b=document.getElementById('tslb');if(b){b.click();announce('Loop ends here')}}}
document.addEventListener('keydown',tsKeys);
function tsReadText(){const R=TS.res;if(!R||!R.beats||R.beats.length<2)return'';const B=R.beats;const nb=Math.ceil(B.length/4);const N=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];const nm=m=>N[m%12]+(Math.floor(m/12)-1);const out=[];
 for(let b=0;b<nb;b++){const a=B[b*4],z=B[Math.min(B.length-1,b*4+4)]+(b*4+4>=B.length?9:0);const ch=[...new Set((R.chords||[]).filter(c=>c.t>=a-.01&&c.t<z&&c.name!=='N').map(c=>c.name))];const ns=(R.notes||[]).filter(n=>n.t>=a-.03&&n.t<z-.03).map(n=>nm(n.m));
  const hs=(R.hits||[]).filter(h=>h.t>=a-.03&&h.t<z-.03);const dr=hs.length?['kick','snare','hat'].map(k=>{const c=hs.filter(h=>h.k===k).length;return c?`${c} ${k==='hat'?'hi-hat':k}${c>1?'s':''}`:''}).filter(Boolean).join(', '):'';
  const parts=[];if(ch.length)parts.push((ch.length>1?'chords ':'chord ')+ch.join(', '));if(ns.length)parts.push('notes '+ns.join(' '));if(dr)parts.push(dr);out.push(`<li>Bar ${b+1}: ${parts.length?esc(parts.join('; ')):'rest'}</li>`)}
 return out.join('')}
function tsA11yPanel(){const tab=document.querySelector('.tstab');if(!tab||document.getElementById('tsread'))return;const sec=tab.closest('section');if(!sec)return;
 sec.insertAdjacentHTML('beforeend',`<p class="hint" id="tskeys">Keys: Space plays or pauses. In the tab, the arrow keys move a bar, Enter plays from there, Home goes back to the start, [ and ] set a loop.</p><details id="tsread" class="tsread"><summary>Read the transcription as text</summary><ol class="tsreadl">${tsReadText()}</ol></details>`)}
new MutationObserver(()=>{if(/^#tools-isolate/.test(location.hash))tsA11yPanel()}).observe(document.getElementById('main'),{childList:true,subtree:true});
/* small fixes found by an automated check */
/* name selects and empty table headers that a screen reader would otherwise read as blank */
function a11yNames(){document.querySelectorAll('#main select:not([aria-label]):not([id]),#main select.psel:not([aria-label])').forEach(x=>{if(x.labels&&x.labels.length)return;const box=x.closest('.pickrow,.row,label,div');let t='';const ey=box&&box.querySelector('.eyebrow,h3,h4,b');if(ey&&!ey.contains(x))t=ey.textContent.trim();if(!t){let p=x.previousElementSibling;if(p)t=p.textContent.trim()}x.setAttribute('aria-label',(t||'Choose an option').slice(0,60))});
 document.querySelectorAll('#main th').forEach(th=>{if(!th.textContent.trim()&&!th.querySelector('.sr-only')){th.innerHTML='<span class="sr-only">Listen</span>'}})}
/* keep the heading outline in order for screen readers (a section heading never skips a level) */
let _hoT=0;function a11yHeadings(){const hs=[...document.querySelectorAll('#main h1,#main h2,#main h3,#main h4,#main h5,#main h6')];let prev=0;hs.forEach(h=>{const lv=+h.tagName[1];h.removeAttribute('aria-level');const want=prev&&lv>prev+1?prev+1:!prev&&lv>2?lv:lv;if(want!==lv)h.setAttribute('aria-level',want);prev=want})}
new MutationObserver(()=>{clearTimeout(_hoT);_hoT=setTimeout(()=>{a11yHeadings();a11yNames()},80)}).observe(document.getElementById('main'),{childList:true,subtree:true});

applyA11y();a11yChrome();a11yRoute();
Object.assign(window,{applyA11y,a11y,announce,tsReadText});

